CREATE TABLE IF NOT EXISTS nestdutio_domains(id VARCHAR(64) PRIMARY KEY,project_id VARCHAR(64) NOT NULL,domain VARCHAR(253) NOT NULL,token VARCHAR(64) NOT NULL,state VARCHAR(24) NOT NULL,verified_at VARCHAR(32),expires_at VARCHAR(32),last_error VARCHAR(64) NOT NULL DEFAULT '',created_at VARCHAR(32) NOT NULL,updated_at VARCHAR(32) NOT NULL,UNIQUE KEY nestdutio_project_domain(project_id,domain),KEY nestdutio_domains_state(state,updated_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS nestdutio_domain_bindings(domain VARCHAR(253) PRIMARY KEY,claim_id VARCHAR(64) NOT NULL UNIQUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
